"""Compare the files regenerated by reproduce_v02.sh (separate clone ../../repro) with the committed manifest
and committed files. Writes out/repro_compare.json and out/repro_compare.txt."""
import hashlib, os, subprocess, json, gzip, re, io
import pandas as pd
RP = '../../repro'
man = subprocess.run(['git', 'show', 'HEAD:data/MANIFEST.sha256'], capture_output=True, text=True, cwd=RP).stdout
ent = [l.split() for l in man.strip().split('\n')]
same, diff, missing = [], [], []
for h, p in ent:
    fp = os.path.join(RP, 'data', p)
    if not os.path.exists(fp): missing.append(p); continue
    (same if hashlib.sha256(open(fp, 'rb').read()).hexdigest() == h else diff).append(p)
def committed(p):
    return subprocess.run(['git', 'show', f'HEAD:data/{p}'], capture_output=True, cwd=RP).stdout
# classify byte-level differences
gz_content_equal, gz_content_diff, other = [], [], []
for p in diff:
    if p.endswith('.gz'):
        a = gzip.decompress(open(os.path.join(RP, 'data', p), 'rb').read()); b = gzip.decompress(committed(p))
        (gz_content_equal if a == b else gz_content_diff).append(p)
    else:
        other.append(p)
detail = {}
for p in other:
    new = pd.read_csv(os.path.join(RP, 'data', p)) if p.endswith('.csv') else None
    old = pd.read_csv(io.BytesIO(committed(p))) if p.endswith('.csv') else None
    if new is not None:
        cols = [c for c in new.columns if c in old.columns]
        dc = [c for c in cols if not (len(new) == len(old) and new[c].astype(str).equals(old[c].astype(str)))]
        detail[p] = dict(rows_new=len(new), rows_old=len(old), differing_columns=dc)
    else:
        detail[p] = 'non-csv'
# texts regenerated outside data/
texts = {}
for t in ['report.md', 'note/numbers_v02.tex', 'PREDICTIONS.md', 'note/note_v0.2.diff']:
    r = subprocess.run(['git', 'diff', '--numstat', 'HEAD', '--', t], capture_output=True, text=True, cwd=RP).stdout.strip()
    texts[t] = r or 'identical'
rdiff = subprocess.run(['git', 'diff', '-U0', 'HEAD', '--', 'report.md'], capture_output=True, text=True, cwd=RP).stdout
rlines = [l for l in rdiff.split('\n') if l.startswith(('+', '-')) and not l.startswith(('+++', '---'))]
status = subprocess.run(['git', 'status', '--porcelain'], capture_output=True, text=True, cwd=RP).stdout.strip().split('\n')
log = open('../../repro_logs/run.log').read()
m = re.search(r'(\d+\.\d+) real', log); wall = float(m.group(1)) if m else None
rss = re.search(r'(\d+)\s+maximum resident set size', log)
ex = re.search(r'exit (\d+)', log)
res = dict(entries=len(ent), identical=len(same), differ=len(diff), missing=missing, gz_content_equal=len(gz_content_equal),
           gz_content_diff=gz_content_diff, other_diff=detail, texts=texts, report_changed_lines=rlines[:40],
           untracked_or_modified=[s for s in status if s][:60], wall_h=f'{wall/3600:.2f}' if wall else 'n/a',
           exit=ex.group(1) if ex else 'n/a', maxrss_top_MB=round(int(rss.group(1)) / 2**20) if rss else None)
json.dump(res, open('out/repro_compare_raw.json', 'w'), indent=1)
print(json.dumps({k: v for k, v in res.items() if k not in ('report_changed_lines',)}, indent=1)[:4000])
print('\n'.join(rlines[:40]))
